def find_maximum_minimum_mex(n, m, subarrays):
    def can_achieve_mex(mid):
        # Create an array to track the presence of numbers up to mid
        presence = [False] * (mid + 1)
        for l, r in subarrays:
            for i in range(l - 1, r):
                if 0 <= a[i] <= mid:
                    presence[a[i]] = True
        # Find the first missing number in the presence array
        for i in range(mid + 1):
            if not presence[i]:
                return i
        return mid + 1

    # Binary search for the maximum possible minimum mex
    low, high = 0, n
    while low < high:
        mid = (low + high + 1) // 2
        if can_achieve_mex(mid) <= mid:
            low = mid
        else:
            high = mid - 1

    # Construct the array with the found mex
    mex = can_achieve_mex(low)
    a = [0] * n
    used = set()
    for i in range(n):
        if mex not in used:
            a[i] = mex
            used.add(mex)
        else:
            for j in range(n):
                if j not in used:
                    a[i] = j
                    used.add(j)
                    break

    return low, a

