def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    subarrays = []
    index = 2
    for _ in range(m):
        l_i = int(data[index]) - 1
        r_i = int(data[index + 1]) - 1
        subarrays.append((l_i, r_i))
        index += 2

    def can_achieve_mex(mid):
        a = [0] * n
        for i in range(n):
            a[i] = i
        for l, r in subarrays:
            if r - l + 1 >= mid:
                for i in range(mid):
                    a[l + i] = min(a[l + i], i)
        return all(a[i] >= i for i in range(mid))

    low, high = 0, n + 1
    best_mex = 0

    while low < high:
        mid = (low + high) // 2
        if can_achieve_mex(mid):
            best_mex = mid
            low = mid + 1
        else:
            high = mid

    a = [0] * n
    for i in range(n):
        a[i] = i
    for l, r in subarrays:
        if r - l + 1 >= best_mex:
            for i in range(best_mex):
                a[l + i] = min(a[l + i], i)

    print(best_mex)
    print(' '.join(map(str, a)))
